(* [comment removed for export] *)
Definition xinsideG (bc : bctx) (b1 : expr) (k1 : Z) (n1 : expr) (b2 : expr) (k2 : Z) (n2 : expr) : bool :=
  if shares_var b1 b2 then xinside0B bc b1 k1 n1 b2 k2 n2
  else if novars b2 then xinside_numB bc b1 k1 n1 b2 k2 n2
  else false.
Definition sub_itvG (bc : bctx) (b : expr) (k n : Z) (c : saddr) (m : expr) : bool :=
  if (if (expr_eqb b (a_base c) && Z.leb (a_off c) k)%bool then
        match xloB bc m with Some ml => Z.leb (k + n) (a_off c + ml) | None => false end
      else false)
  then true
  else if ((0 <=? n) && (n <? two63z))%Z%bool then xinsideG bc b k (ELit n) (a_base c) (a_off c) m else false.
Fixpoint in_sidesG (bc : bctx) (D : list (saddr * expr)) (b : expr) (k n : Z) : bool :=
  match D with
  | [] => false
  | (c, m) :: r => if sub_itvG bc b k n c m then true else in_sidesG bc r b k n
  end.

