Definition prune1pcK2 (bc : bctx) (sp : sprep) (wa : saddr) (w : nat) (wv : expr) (K : kentry) (same : bool)
  (br2 : option (Z * Z)) : pk_res :=
  let k := a_off wa in
  let wb := a_base wa in
  let zfK (mk : saddr -> expr -> kentry) (kb : expr) (kk : Z) (len : expr) :=
    if same then
      match len with
      | ELit l0 => if ((0 <? l0) && (l0 <? two64) && ((kk + l0 <=? k) || (k + Z.of_nat w <=? kk)))%Z%bool then PKeep
                   else PRepl (ktrim mk kb kk l0 k w)
      | _ => if Z.leb (k + Z.of_nat w) kk then PKeep else PRepl (kcutB bc mk wb k (elen w) kb kk len)
      end
    else if ranges_apart_pcB bc sp wb k (elen w) br2 kb kk len then PKeep
    else match kcutB bc mk wb k (elen w) kb kk len with
         | [] => if ranges_apart_pcB bc sp wb k (elen w) br2 kb kk len then PKeep else PRepl []
         | cut => PRepl cut
         end in
  match K with
  | KAlign _ _ | KRange _ _ _ | KWr _ _ | KDisj _ _ _ _ => PKeep
  | KImg lo hi =>
      match wb with
      | ELit 0 =>
          let r1 := if Z.ltb lo (Z.min k hi) then [KImg lo (Z.min k hi)] else [] in
          let lo2 := Z.max lo (k + Z.of_nat w) in
          let r2 := if Z.ltb lo2 hi then [KImg lo2 hi] else [] in
          PRepl (r1 ++ r2)
      | _ => if Z.ltb (hi - lo) (2 ^ 64) then
               (if ranges_apart_pB bc sp wb k (elen w) (ELit 0) lo (ELit (hi - lo)) then PKeep else PRepl [])
             else PRepl []
      end
  | KZero (SA kb kk) len => zfK KZero kb kk len
  | KFill (SA kb kk) len c => zfK (fun a n => KFill a n c) kb kk len
  | KUnk (SA kb kk) len => zfK KUnk kb kk len
  | KWord (SA kb kk) w' v =>
      if same then (if (Z.leb (kk + Z.of_nat w') k || Z.leb (k + Z.of_nat w) kk)%bool then PKeep else PRepl (kword_cut kb kk w' v k w))
      else if ranges_apart_pcB bc sp wb k (elen w) br2 kb kk (elen w') then PKeep
      else if (Nat.eqb w 1 && Nat.eqb w' 1 && expr_eqb wv v)%bool then PKeep
      else if ranges_apart_pcB bc sp wb k (elen w) br2 kb kk (elen w') then PKeep else PRepl []
  | KBlob (SA kb kk) len bk =>
      if same then
        match len with
        | ELit l0 => let l := (l0 mod 2 ^ 64)%Z in
                     if (Z.leb (kk + l) k || Z.leb (k + Z.of_nat w) kk)%bool then PKeep else PRepl []
        | _ => if Z.leb (k + Z.of_nat w) kk then PKeep else PRepl []
        end
      else if ranges_apart_pcB bc sp wb k (elen w) br2 kb kk len then PKeep else PRepl []
  end.

Fixpoint chainK2b (bc : bctx) (sxs : list stx) (K : kentry) (okb : option expr) (same_of : positive -> bool) (br2 : option (Z * Z)) : list kentry :=
  match sxs with
  | [] => [K]
  | sx :: rest =>
      match prune1pcK2 bc (sx_sp sx) (sx_a sx) (sx_w sx) (sx_v sx) K (same_of (sx_bid sx)) br2 with
      | PKeep => chainK2b bc rest K okb same_of br2
      | PRepl l =>
          match okb with
          | Some kb =>
              flat_map (fun K' => match kbase K' with
                                  | Some kb' => if expr_eqb kb' kb then chainK2b bc rest K' okb same_of br2 else chain_slow bc rest [K']
                                  | None => chain_slow bc rest [K']
                                  end) l
          | None => chain_slow bc rest l
          end
      end
  end.
Fixpoint stores_part2 (bc : bctx) (sxs : list stx) : list kentry :=
  match sxs with
  | [] => []
  | sx :: newer => stores_part2 bc newer ++ chainK2b bc newer (KWord (sx_a sx) (sx_w sx) (sx_v sx)) (Some (a_base (sx_a sx))) (Pos.eqb (sx_bid sx)) (sx_br sx)
  end.
(* [comment removed for export] *)
Fixpoint in_sides1 (bc : bctx) (D : list (saddr * expr)) (b : expr) (k n : Z) : bool :=
  match D with
  | [] => false
  | (c, m) :: r =>
      if (if (expr_eqb b (a_base c) && Z.leb (a_off c) k)%bool then
            match xloB bc m with Some ml => Z.leb (k + n) (a_off c + ml) | None => false end
          else false)
      then true else in_sides1 bc r b k n
  end.
(* [comment removed for export] *)
Definition gval2 : Type := (positive * expr * option (Z * Z) * (Z * Z))%type.
Definition verdict2 (bc : bctx) (sx : stx) (g : gval2) : bool :=
  match g with
  | (b, gb, obr, (glo, ghi)) =>
      let k := a_off (sx_a sx) in
      if Pos.eqb b (sx_bid sx) then ((k + Z.of_nat (sx_w sx) <=? glo) || (ghi <=? k))%Z%bool else
      if match sp_rng (sx_sp sx), obr with
         | Some (lo1, hi1), Some (lo2, hi2) =>
             (Z.leb (hi1 + k + sx_m1 sx - lo2) glo || Z.leb ghi (lo1 + k - hi2))%bool
         | _, _ => false
         end then true
      else in_sidesG bc (sp_D (sx_sp sx)) gb glo (ghi - glo)
  end.
Fixpoint mk_fl2 (bc : bctx) (g : gval2) (sxs : list stx) : list (stx * list stx) :=
  match sxs with
  | [] => []
  | sx :: rest => if verdict2 bc sx g then mk_fl2 bc g rest else (sx, rest) :: mk_fl2 bc g rest
  end.
Definition gfl2 : Type := (gval2 * list (stx * list stx))%type.
(* [comment removed for export] *)
Definition g2_of (t : ntab) (g : gval) : gval2 :=
  match g with (b, obr, h) => (b, match pt_get (nt_info t) b with Some bi => bi_base bi | None => ELit 0 end, obr, h) end.
Definition mk_gl2 (bc : bctx) (t : ntab) (bnds : gtab) (sxs : list stx) : ptree gfl2 := pt_map (fun g => let g2 := g2_of t g in (g2, mk_fl2 bc g2 sxs)) bnds.
(* [comment removed for export] *)
Definition kraw (K : kentry) : option Z :=
  match K with
  | KWord (SA _ _) w _ => Some (Z.of_nat w)
  | KZero (SA _ _) (ELit z) | KUnk (SA _ _) (ELit z) | KFill (SA _ _) (ELit z) _ | KBlob (SA _ _) (ELit z) _ => Some z
  | _ => None
  end.
Definition kregular (K : kentry) : bool :=
  match kraw K with Some z => ((0 <? z) && (z <? two63z))%Z%bool | None => false end.
Definition inb2 (g : gval2) (K : kentry) (ei : einfo) : bool :=
  match ei_m ei, g with
  | Some m, (b, _, obr, (lo, hi)) =>
      kregular K && Pos.eqb b (ei_bid ei) && obr_eqb obr (ei_br ei) && Z.leb lo (ei_k ei) && Z.leb (ei_k ei + m) hi
  | _, _ => false
  end%bool.
Fixpoint chainKF2 (bc : bctx) (fl : list (stx * list stx)) (K : kentry) (okb : option expr) (same_of : positive -> bool)
         (br2 : option (Z * Z)) : list kentry :=
  match fl with
  | [] => [K]
  | (sx, rest) :: fl' =>
      match prune1pcK2 bc (sx_sp sx) (sx_a sx) (sx_w sx) (sx_v sx) K (same_of (sx_bid sx)) br2 with
      | PKeep => chainKF2 bc fl' K okb same_of br2
      | PRepl l =>
          match okb with
          | Some kb =>
              flat_map (fun K' => match kbase K' with
                                  | Some kb' => if expr_eqb kb' kb then chainK2b bc rest K' okb same_of br2 else chain_slow bc rest [K']
                                  | None => chain_slow bc rest [K']
                                  end) l
          | None => chain_slow bc rest l
          end
      end
  end.
Fixpoint entriesG2 (bc : bctx) (sxs : list stx) (gl : ptree gfl2) (kn : list kentry) (infos : list (option einfo)) : list kentry :=
  match kn, infos with
  | K :: rest, oi :: irest =>
      (match oi with
       | Some ei =>
           let okb := kbase K in
           let same_of := match okb with Some _ => Pos.eqb (ei_bid ei) | None => fun _ => false end in
           let br2 := match okb with Some _ => ei_br ei | None => None end in
           match pt_get gl (ei_gid ei) with
           | Some (g, fl) => if inb2 g K ei then chainKF2 bc fl K okb same_of br2 else chainK2b bc sxs K okb same_of br2
           | None => chainK2b bc sxs K okb same_of br2
           end
       | None => chainK2b bc sxs K None (fun _ => false) None
       end) ++ entriesG2 bc sxs gl rest irest
  | _, _ => []
  end.
Definition carryG2 (bc : bctx) (log : list sentry) (kn : list kentry) : list kentry :=
  let '(sxs, t0) := mk_stxs bc log nt_empty in
  let '(r, gs) := scan_entries bc kn t0 gst_empty in
  let '(infos, t1) := r in
  stores_part2 bc sxs ++ entriesG2 bc sxs (mk_gl2 bc t1 (gs_bnds gs) sxs) kn infos.
Definition carryK2 (bc : bctx) (log : list sentry) (kn : list kentry) (hints : list bool)
  : list kentry * list sidecond * list bool :=
  match log, hints with
  | [], _ => (kn, [], hints)
  | _, [] => (carryG2 bc log kn, [], [])
  | _, _ => carryB bc log kn hints
  end.

