(* [comment removed for export] *)
Lemma verdict2_cases : forall bc sx b gb obr glo ghi,
  verdict2 bc sx (b, gb, obr, (glo, ghi)) = true ->
  (Pos.eqb b (sx_bid sx) = true /\ (a_off (sx_a sx) + Z.of_nat (sx_w sx) <= glo \/ ghi <= a_off (sx_a sx)))
  \/ (Pos.eqb b (sx_bid sx) = false /\
      ((exists lo1 hi1 lo2 hi2, sp_rng (sx_sp sx) = Some (lo1, hi1) /\ obr = Some (lo2, hi2)
          /\ (hi1 + a_off (sx_a sx) + sx_m1 sx - lo2 <= glo \/ ghi <= lo1 + a_off (sx_a sx) - hi2))
