Record sdinfo := SDI { sd_c : saddr; sd_m : expr; sd_xlom : option Z; sd_nwc : bool; sd_nwm : bool; sd_nov : bool;
                       sd_xloc : option Z; sd_xhic : option Z }.
Definition mk_sdi (bc : bctx) (c : saddr) (m : expr) : sdinfo :=
  SDI c m (xloB bc m) (lin_nowrapRB bc (a_base c)) (lin_nowrapRB bc m) (novars (a_base c)) (xloB bc (a_base c)) (xhiB bc (a_base c)).
Fixpoint mk_dtab (bc : bctx) (kn : list kentry) : list (sdinfo * sdinfo) :=
  match kn with
  | [] => []
  | KDisj c1 m1 c2 m2 :: rest => (mk_sdi bc c1 m1, mk_sdi bc c2 m2) :: mk_dtab bc rest
  | _ :: rest => mk_dtab bc rest
  end.

