Definition xinside0T (bc : bctx) (nw1 : bool) (sd : sdinfo) (b1 : expr) (k1 : Z) (n1 : expr) : bool :=
  let cb := a_base (sd_c sd) in let ck := a_off (sd_c sd) in let m := sd_m sd in
  if lin_ge0T bc (nw1 && true) (sd_nwc sd && true) [(b1, k1)] [(cb, ck)]
  then lin_ge0T bc (sd_nwc sd && (sd_nwm sd && true)) (nw1 && (lin_nowrapRB bc n1 && true)) [(cb, ck); (m, 0%Z)] [(b1, k1); (n1, 0%Z)]
  else false.
Definition xinside_numT (bc : bctx) (br1 : option (Z * Z)) (sd : sdinfo) (k1 : Z) (n1 : expr) : bool :=
  let ck := a_off (sd_c sd) in
  match sd_xloc sd, sd_xhic sd with
  | Some lo2, Some hi2 =>
      if Z.eqb lo2 hi2 then
        match br1, xhiB bc n1, sd_xlom sd with
        | Some (lo1, hi1), Some h1, Some l2 => Z.leb (lo2 + ck) (lo1 + k1) && Z.leb (hi1 + k1 + h1) (lo2 + ck + l2)
        | _, _, _ => false
        end
      else false
  | _, _ => false
  end.
(* [comment removed for export] *)
Definition xinsideT (bc : bctx) (br1 : option (Z * Z)) (nw1 : bool) (sd : sdinfo) (b1 : expr) (k1 : Z) (n1 : expr) : bool :=
  if shares_var b1 (a_base (sd_c sd)) then xinside0T bc nw1 sd b1 k1 n1
  else if sd_nov sd then
    (if xinside_numT bc br1 sd k1 n1 then true
     else if novars n1 then false else xinside0T bc nw1 sd b1 k1 n1)
  else false.
Definition SDOK (bc : bctx) (sd : sdinfo) : Prop := sd = mk_sdi bc (sd_c sd) (sd_m sd).
Lemma xinsideT_eq : forall bc b1 k1 n1 sd,
  SDOK bc sd -> Z.ltb 0 (snd (AX2.deand b1)) = false ->
  xinsideT bc (base_rangeB bc b1) (lin_nowrapRB bc b1) sd b1 k1 n1 = xinsideB bc b1 k1 n1 (a_base (sd_c sd)) (a_off (sd_c sd)) (sd_m sd).
Proof.
