(* [comment removed for export] *)
Definition synT (sd : sdinfo) (b1 : expr) (k1 n : Z) : bool :=
  let c := sd_c sd in
  if (expr_eqb b1 (a_base c) && Z.leb (a_off c) k1)%bool then
    match sd_xlom sd with Some ml => Z.leb (k1 + n) (a_off c + ml) | None => false end
  else false.
Fixpoint sides2 (bc : bctx) (dt : list (sdinfo * sdinfo)) (br1 : option (Z * Z)) (nw1 : bool) (b1 : expr) (k1 n : Z)
  : list (saddr * expr) * list (saddr * expr) :=
  match dt with
  | [] => ([], [])
  | (s1, s2) :: rest =>
      let '(r, rx) := sides2 bc rest br1 nw1 b1 k1 n in
      let x2 := xinsideT bc br1 nw1 s2 b1 k1 (ELit n) in
      let x1 := xinsideT bc br1 nw1 s1 b1 k1 (ELit n) in
      let t2 := if synT s2 b1 k1 n then true else x2 in
      let t1 := if synT s1 b1 k1 n then true else x1 in
      let r1 := if t2 then (sd_c s1, sd_m s1) :: r else r in
      let r1x := if x2 then (sd_c s1, sd_m s1) :: rx else rx in
      (if t1 then (sd_c s2, sd_m s2) :: r1 else r1, if x1 then (sd_c s2, sd_m s2) :: r1x else r1x)
  end.
Lemma sides2_eq : forall bc kn b1 k1 n,
  0 <= n -> n < two64 -> Z.ltb 0 (snd (AX2.deand b1)) = false ->
  sides2 bc (mk_dtab bc kn) (base_rangeB bc b1) (lin_nowrapRB bc b1) b1 k1 n
