Definition mk_sprepF (bc : bctx) (dt : list (sdinfo * sdinfo)) (b1 : expr) (k1 : Z) (w : nat) : sprep :=
  let n := Z.of_nat w in
  if (if (n <? two64)%Z then negb (0 <? snd (AX2.deand b1))%Z else false) then
    let br1 := base_rangeB bc b1 in
    let '(D, Dx) := sides2 bc dt br1 (lin_nowrapRB bc b1) b1 k1 n in
    SPrep br1 (Some n) D Dx
  else mk_sprepB bc b1 k1 (elen w).
Lemma mk_sprepF_eq : forall bc b1 k1 w,
  mk_sprepF bc (mk_dtab bc (bc_fk bc)) b1 k1 w = mk_sprepB bc b1 k1 (elen w).
Proof.
