Fixpoint mk_stxsF (bc : bctx) (dt : list (sdinfo * sdinfo)) (log : list sentry) (t : ntab) : list stx * ntab :=
  match log with
  | [] => ([], t)
  | SE a w v :: older =>
      let '(sxs, t1) := mk_stxsF bc dt older t in
      let '(r, t2) := intern bc t1 (a_base a) in
      let '(bid, bi) := r in
      (sxs ++ [STX a w v (mk_sprepF bc dt (a_base a) (a_off a) w) bid (bi_br bi)], t2)
  end.
Lemma mk_stxsF_eq : forall bc log t, mk_stxsF bc (mk_dtab bc (bc_fk bc)) log t = mk_stxs bc log t.
