Definition carryG3 (bc : bctx) (log : list sentry) (kn : list kentry) : list kentry :=
  let '(sxs, t0) := mk_stxsF bc (mk_dtab bc (bc_fk bc)) log nt_empty in
  let '(r, gs) := scan_entries bc kn t0 gst_empty in
  let '(infos, t1) := r in
  stores_part2 bc sxs ++ entriesG2 bc sxs (mk_gl2 bc t1 (gs_bnds gs) sxs) kn infos.
