Definition carryK3 (bc : bctx) (log : list sentry) (kn : list kentry) (hints : list bool)
  : list kentry * list sidecond * list bool :=
  match log, hints with
  | [], _ => (kn, [], hints)
  | _, [] => (carryG3 bc log kn, [], [])
  | _, _ => carryB bc log kn hints
  end.
