  Fixpoint subset_zip (M cur L : list T) : bool :=
    match M with
    | [] => true
    | K :: M' =>
        match (match cur with X :: cur' => if eqb K X then Some cur' else None | [] => None end) with
        | Some cur' => subset_zip M' cur' L
        | None => match mem_suffix K L with Some cur' => subset_zip M' cur' L | None => false end
        end
    end.
