  Variable full : T -> bool.
  Variable L0 : list T.
  Hypothesis full_hit : forall K X, In X L0 -> eqb K X = true -> full K = true.
  Fixpoint incl_zip (M cur : list T) : bool :=
    match M with
    | [] => true
    | K :: M' =>
        match (match cur with X :: cur' => if eqb K X then Some cur' else None | [] => None end) with
        | Some cur' => incl_zip M' cur'
        | None => if full K then incl_zip M' (match mem_suffix K L0 with Some cur' => cur' | None => cur end) else false
        end
    end.
