Definition safe_rangeF (A : atable) (bc : bctx) (ms : list amap) (b : expr) (off : Z) (len : expr) : bool :=
  if (match xhiB bc len, base_rangeB bc b with
      | Some lh, Some (lo, hi) => (Z.leb (img_lo A) (lo + off) && Z.leb (hi + off + lh) (img_hi A))
      | _, _ => false
      end)%bool then true
  else if (if xinsideB bc b off len (ELit 0) SW_LO (ELit (KHI - SW_LO)) then sw_tracked ms else false) then true
  else if xinsideB bc b off len e_band 0 (ELit BANDLEN) then true
  else inside_mapsF bc ms b off len.
