Definition grant_keep_bF (A : atable) (bc : bctx) (ms : list amap) (K : kentry) : bool :=
  match K with
  | KWord (SA b o) w _ => if Nat.leb w 8 then safe_rangeF A bc ms b o (ELit (Z.of_nat w)) else false
  | KZero (SA b o) l => safe_rangeF A bc ms b o l
  | KBlob (SA b o) l _ => safe_rangeF A bc ms b o l
  | KImg lo hi => true
  | KAlign _ _ => true
  | KRange _ _ _ => true
  | KDisj _ _ _ _ => true
  | KWr (SA b o) n => safe_rangeF A bc ms b o n
