Definition vis_test_fast (A : atable) (bc : bctx) (k0 : list kentry) (bb : expr) (bk : Z) (b n sb : expr) (sk : Z) (sn : expr) (p : expr * expr) : bool :=
  let '(pb, pk) := split_lit (fst p) in
  if (if flat_xB bc pb pk (snd p) then true else flat_xe k0 pb pk (snd p)) then
    if (if ranges_apart_xB bc bb bk n pb pk (snd p) then true else slice_ok k0 bb bk b n p) then
      (if ranges_apart_xB bc sb sk sn pb pk (snd p) then true else shadow_apart_each k0 sb sk sn pb pk (snd p))
    else false
  else false.
Definition vis_add_fast (A : atable) (LIMIT : Z) (cs : acs) (b n : expr) (k : list kentry) : option acs :=
  let k0 := kn cs in let bc := mkbc k0 in
  let '(bb, bk) := split_lit b in
  let '(sb, sk, sn) := shadow_ofB A bc b n in
  match xhiB bc n with
  | Some nhi =>
  if (Z.leb 3 (ealignB bc b) && Z.leb 3 (ealignB bc n) && flat_xB bc bb bk n
      && expr_vars_lt (nxt cs) b && expr_vars_lt (nxt cs) n
      && forallb (vis_test_fast A bc k0 bb bk b n sb sk sn) (a_vis cs)
      && shd_end_okB bc b n && sw_off_ok A
      && Z.leb (a_eager cs + a_abytes cs + vis_cost nhi) LIMIT)%bool
  then Some (ACS (mk_ss (pc cs) (s_regs (a_ss cs)) (shadow_factsB A bc (a_maps cs) b n ++ k) (nxt cs))
                (a_maps cs) (a_totsz cs) (a_ylo cs) (a_eager cs)
                ((b, n) :: a_vis cs) (a_ghost cs) (a_abytes cs + vis_cost nhi) (a_brk cs) (a_fd cs) (a_tidset cs))
  else None
  | None => None
  end.
