(* [comment removed for export] *)
Definition hverdict (bc : bctx) (sp : sprep) (uk : Z) (un : expr) (g : gval2) : bool :=
  match g with
  | (b, gb, obr, (glo, ghi)) =>
      match un with
      | ELit z1 =>
          let m1 := zlit64 z1 in
          if match sp_rng sp, obr with
             | Some (lo1, hi1), Some (lo2, hi2) => ((hi1 + uk + m1 <=? lo2 + glo) || (hi2 + ghi <=? lo1 + uk))%Z%bool
             | _, _ => false
             end then true
          else in_sidesG bc (sp_D sp) gb glo (ghi - glo)
      | _ =>
          if match sp_rng sp, obr, sp_h1 sp with
             | Some (lo1, hi1), Some (lo2, hi2), Some h1 => ((hi1 + uk + h1 <=? lo2 + glo) || (hi2 + ghi <=? lo1 + uk))%Z%bool
             | _, _, _ => false
             end then true
          else in_sidesGx bc (sp_Dx sp) gb glo (ghi - glo)
      end
  end.
(* [comment removed for export] *)
Definition inbH (g : gval2) (K : kentry) (ei : einfo) : bool :=
  inb2 g K ei && match K with KWord _ w _ => Nat.leb w 8 | _ => true end.

Fixpoint havocG (bc : bctx) (sp : sprep) (ub : expr) (uk : Z) (un : expr) (hg : ptree (gval2 * bool))
         (kn : list kentry) (infos : list (option einfo)) : list kentry :=
  match kn, infos with
  | K :: rest, oi :: irest =>
      (match oi with
       | Some ei =>
           match pt_get hg (ei_gid ei) with
           | Some (g, true) => if inbH g K ei then [K] else havoc1pB bc sp ub uk un K
           | _ => havoc1pB bc sp ub uk un K
           end
       | None => havoc1pB bc sp ub uk un K
       end) ++ havocG bc sp ub uk un hg rest irest
  | _, _ => []
  end.

Definition mk_hg (bc : bctx) (sp : sprep) (uk : Z) (un : expr) (t1 : ntab) (g : gval) : gval2 * bool :=
  let g2 := g2_of t1 g in (g2, hverdict bc sp uk un g2).
Definition kn_havocBF (bc : bctx) (ub : expr) (uk : Z) (un : expr) : list kentry :=
  let sp := mk_sprepB bc ub uk un in
  let '(r, gs) := scan_entries bc (bc_fk bc) nt_empty gst_empty in
  let '(infos, t1) := r in
  havocG bc sp ub uk un (pt_map (mk_hg bc sp uk un t1) (gs_bnds gs)) (bc_fk bc) infos.
Definition kn_havocF (k : list kentry) := kn_havocBF (mkbc k).

