  kregular K = true -> kdescr K = Some (kb, kk, Some m) ->
  match K with KWord _ w _ => Nat.leb w 8 | _ => true end = true ->
  glo <= kk -> kk + m <= ghi ->
  hverdict bc sp uk un (b, kb, base_rangeB bc kb, (glo, ghi)) = true ->
  kentry_apart_bpB bc sp ub uk un K = true.
Proof.
