Lemma havocG_eq : forall fk sp ub uk un bnds kn infos t1,
  NTI (mkbc fk) t1 -> Forall2 (EINF (mkbc fk) t1) kn infos ->
  havocG (mkbc fk) sp ub uk un (pt_map (mk_hg (mkbc fk) sp uk un t1) bnds) kn infos
