Definition check_fast := ltac:(let t := eval cbv delta [check] in check in
  let t := swap1 t run_block_gc run_block_gc_fast in
  let t := swap1 t entails entails_fast in
  let t := swap1 t entails_h entails_h_fast in
  let t := swap1 t node_mmap2 node_mmap2_fast in
  let t := swap1 t node_diamond_join node_diamond_join_fast in
  let t := swap1 t node_x node_x_fast in
  let t := swap1 t node_brk2s node_brk2s_fast in
  let t := swap1 t node_brk2 node_brk2_fast in
  let t := swap1 t node_droprange node_droprange_fast in
  exact t).

Lemma check_fast_eqc : check_fast = check.
Proof.
  unfold check_fast.
  rewrite ?run_block_gc_fast_eqc, ?entails_fast_eqc, ?entails_h_fast_eqc, ?node_mmap2_fast_eqc,
    ?node_diamond_join_fast_eqc, ?node_x_fast_eqc, ?node_brk2s_fast_eqc, ?node_brk2_fast_eqc,
    ?node_droprange_fast_eqc.
  reflexivity.
Qed.

